//! 🧭️ Authored creation rules inspect original vector items and foreign keys through separately funded native cursors.
use super::*;
use crate::reference::{ReferenceCollection,ReferenceLookup};
/// 🪪️ Each rule reads one actual source predicate or one retained original identifier.
pub enum CreationRule<'a>{Predicate(bool),Reference(RetainedCloneRef<'a,u32>,&'static[ReferenceCollection])}
/// 🧬️ Typed schema rules provide bounded original item readers after their declared base validation.
pub trait CreationRuleSource:Send+Sync+'static{type Payload:Send+Sync+'static;type Base:RowCreationValidation<Self::Payload>;fn base()->Self::Base;fn len(input:&Self::Payload)->Result<usize,ValueError>;fn read(input:RetainedCloneRef<'_,Self::Payload>,index:usize)->Result<CreationRule<'_>,ValueError>;fn reference_target(input:RetainedCloneRef<'_,Self::Payload>,index:usize)->Result<RetainedCloneRef<'_,u32>,ValueError>{match Self::read(input,index)?{CreationRule::Reference(key,_)=>Ok(key),_=>Err(invalid())}}}
/// 🧳️ The failed original item index survives child closure so diagnostics retain the actual foreign identifier.
pub struct RuleRowCreationValidation<S:CreationRuleSource>{input:Option<RetainedCloneBinding>,original:Option<RetainedCloneBinding>,base:Option<Box<S::Base>>,reference:Option<Box<ReferenceLookup>>,index:usize,collection:usize,found:bool,result:Option<Option<RowOutcome>>,phase:u8,closing:bool}
impl<S:CreationRuleSource> RuleRowCreationValidation<S>{pub fn new()->Self{Self{input:None,original:None,base:None,reference:None,index:0,collection:0,found:false,result:None,phase:0,closing:false}}fn reference(input:RetainedCloneRef<'_,S::Payload>,index:usize)->Result<(RetainedCloneRef<'_,u32>,&'static[ReferenceCollection]),ValueError>{if let CreationRule::Reference(key,collections)=S::read(input,index)?{if collections.is_empty(){return Err(invalid());}Ok((key,collections))}else{Err(invalid())}}fn extra()->usize{4*size_of::<usize>()+2*size_of::<CreationRule<'static>>()+2*size_of::<Option<RowOutcome>>()+2}}
impl<S:CreationRuleSource> RowCreationValidation<S::Payload> for RuleRowCreationValidation<S>{
 fn demand(&self,input:RetainedCloneRef<'_,S::Payload>,original:RetainedCloneRef<'_,EnergyModelSnapshot>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.phase==99{return Err(invalid());}input.check_binding(&self.input)?;original.check_binding(&self.original)?;let extra=Self::extra();match self.phase{0=>nested(scalar(input.binding_copy_bytes()),1),1=>nested(scalar(original.binding_copy_bytes()),1),2=>Ok(birth::<S::Base>()),3=>nested(self.base.as_ref().ok_or_else(invalid)?.demand(input,original,body.saturating_sub(extra))?,extra),4=>nested(cursor_demand(&self.base,body.saturating_sub(1))?,1),5=>Ok(scalar(2*size_of::<S::Payload>()+extra)),6=>Ok(birth::<ReferenceLookup>()),7=>nested(self.reference.as_ref().ok_or_else(invalid)?.demand(original,Self::reference(input,self.index)?.0)?,2),8=>nested(cursor_demand(&self.reference,body.saturating_sub(extra))?,extra),_=>Err(invalid())}}
 fn advance(&mut self,input:RetainedCloneRef<'_,S::Payload>,original:RetainedCloneRef<'_,EnergyModelSnapshot>,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.demand(input,original,body)?;if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()));}let extra=Self::extra();let mut p=receipt(d);match self.phase{0=>{p=add(input.bind(&mut self.input,child(g,1))?.ok_or_else(invalid)?,1)?;self.phase=1;},1=>{p=add(original.bind(&mut self.original,child(g,1))?.ok_or_else(invalid)?,1)?;self.phase=2;},2=>{self.base=Some(Box::new(S::base()));self.phase=3;},3=>{let c=self.base.as_mut().ok_or_else(invalid)?;p=add(c.advance(input,original,body.saturating_sub(extra),child(g,extra)).map_err(|e|tag(e,extra))?.progress(),extra)?;if let Some(result)=c.result(){if result.is_some(){self.result=Some(result);}c.begin_close();self.phase=4;}},4=>{p=add(close_cursor(&mut self.base,child(g,1)).map_err(|e|tag(e,1))?,1)?;if self.base.is_none(){self.phase=if self.result.is_some(){99}else{5};}},5=>{if self.index>=S::len(input.get())?{self.result=Some(None);self.phase=99;}else{match S::read(input,self.index)?{CreationRule::Predicate(valid)=>{if valid{self.index+=1;}else{self.result=Some(Some(RowOutcome::Invalid));self.phase=99;}},CreationRule::Reference(_,collections)=>{if collections.is_empty(){return Err(invalid().with_retained_progress(p));}self.collection=0;self.phase=6;}}}},6=>{let(_,collections)=Self::reference(input,self.index)?;self.reference=Some(Box::new(ReferenceLookup::new(*collections.get(self.collection).ok_or_else(invalid)?)));self.phase=7;},7=>{let c=self.reference.as_mut().ok_or_else(invalid)?;p=add(c.advance(original,Self::reference(input,self.index)?.0,child(g,2)).map_err(|e|tag(e,2))?.progress(),2)?;if let Some(found)=c.result(){self.found=found;c.begin_close();self.phase=8;}},8=>{p=add(close_cursor(&mut self.reference,child(g,extra)).map_err(|e|tag(e,extra))?,extra)?;if self.reference.is_none(){if self.found{self.index+=1;self.phase=5;}else if self.collection+1<Self::reference(input,self.index)?.1.len(){self.collection+=1;self.phase=6;}else{self.result=Some(Some(RowOutcome::InvalidReference));self.phase=99;}}},_=>return Err(invalid())}semio_framework_value::retained_clone::admit_retained_clone_progress(g,p,"original Energy creation rule")?;Ok(if self.phase==99{RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 fn result(&self)->Option<Option<RowOutcome>>{self.result}
 fn reference_index(&self)->Option<usize>{(self.result==Some(Some(RowOutcome::InvalidReference))).then_some(self.index)}
 fn begin_close(&mut self){self.closing=true;if let Some(c)=self.reference.as_mut(){c.begin_close();}if let Some(c)=self.base.as_mut(){c.begin_close();}}
}
impl<S:CreationRuleSource> CursorClose for RuleRowCreationValidation<S>{fn close_demand(&self,b:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid());}if self.reference.is_some(){return cursor_demand(&self.reference,b);}if self.base.is_some(){return cursor_demand(&self.base,b);}RetainedCloneBinding::close_demand(if self.input.is_some(){&self.input}else{&self.original},b)}fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.close_demand(g.maximum_copy_bytes)?;if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()));}if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()));}if self.reference.is_some(){return close_cursor(&mut self.reference,g).map(RetainedCloneStep::Progress);}if self.base.is_some(){return close_cursor(&mut self.base,g).map(RetainedCloneStep::Progress);}let s=RetainedCloneBinding::close_one(if self.input.is_some(){&mut self.input}else{&mut self.original},g)?;Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(s.progress())}else{RetainedCloneStep::Progress(s.progress())})}fn terminal_is_empty(&self)->bool{self.closing&&self.reference.is_none()&&self.base.is_none()&&self.input.is_none()&&self.original.is_none()}}
impl<S:CreationRuleSource> Drop for RuleRowCreationValidation<S>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original creation rules retain source or foreign-key cursor custody");}}
